SELECT *
FROM ASSET_APP_SERVER
WHERE ASSET_ID = #{assetId}
  AND SERVER_PORT = #{serverPort}
  AND LINK_STATUS IS NULL
ORDER BY SERVER_PORT

SELECT *
FROM ASSET_APP_SERVER
WHERE ASSET_ID = #{assetId}
  AND SERVER_PORT = #{serverPort}
  AND LINK_STATUS IS NOT NULL
ORDER BY SERVER_PORT

SELECT *
FROM ASSET_APP_SERVER
WHERE ASSET_ID = #{assetId}
  AND SERVER_PORT = #{serverPort}
  AND LINK_IP = #{linkIp}
  AND LINK_STATUS IS NOT NULL
